export function InteractiveMap({
  zoom = "{{zoom}}",
  markerLabel = "{{markerLabel}}",
  accent = "{{accent}}",
  showLabels = {{showLabels}},
}) {
  const markers = [
    { left: "30%", top: "38%", label: markerLabel },
    { left: "64%", top: "56%", label: "Riverside Cafe" },
  ];
  return (
    <div style={{ maxWidth: 360, font: "12px/1.4 system-ui, sans-serif", color: "#241430" }}>
      <div style={{ position: "relative", aspectRatio: "4 / 3", overflow: "hidden", borderRadius: 12,
        border: "1px solid #24143022", background: "linear-gradient(#D9C8F0, #BFD9F2)", cursor: "grab" }}>
        <div className="map-content" style={{ position: "absolute", inset: 0, transformOrigin: "center",
          transform: `scale(${zoom})`,
          backgroundImage: "repeating-linear-gradient(0deg, #24143014 0 1px, transparent 1px 40px), repeating-linear-gradient(90deg, #24143014 0 1px, transparent 1px 40px)" }}>
          {markers.map((m) => (
            <details key={m.label} style={{ position: "absolute", left: m.left, top: m.top, listStyle: "none" }}>
              <summary
                style={{ display: "block", width: 18, height: 18, borderRadius: "50% 50% 50% 0",
                  transform: "translate(-50%, -100%) rotate(-45deg)", cursor: "pointer", border: "2px solid #FAF7F2",
                  background: accent, listStyle: "none" }}
                aria-label={`Marker: ${m.label}`}
              />
              <div style={{ position: "absolute", left: 0, bottom: "calc(100% + 6px)", padding: "4px 8px",
                borderRadius: 6, background: "#241430", color: "#FAF7F2", fontSize: 11, whiteSpace: "nowrap" }}>
                {m.label}
              </div>
              {showLabels && (
                <span style={{ position: "absolute", top: 2, left: 22, fontSize: 10, color: "#241430cc", whiteSpace: "nowrap" }}>
                  {m.label}
                </span>
              )}
            </details>
          ))}
        </div>
      </div>
      <style>{`
        @media (prefers-reduced-motion: no-preference) {
          .map-content { transition: transform .2s ease; }
        }
      `}</style>
    </div>
  );
}
